#! /bin/sh
# regen-conf.sh -- regenerate src/9share_conf.c from grammars/9share.hbnf.
#
# Only a maintainer who changes the grammar needs this; the generated file is committed and the
# package builds without hbnf.  hbnf is at https://github.com/moebiusV/hbnf :
#
#     git clone https://github.com/moebiusV/hbnf && cd hbnf && gprbuild -P hbnf.gpr
#     HBNF=/path/to/hbnf/hbnf HBNF_TEMPLATES=/path/to/hbnf/templates tools/regen-conf.sh
#
# (On a system without the static Ada runtime, link hbnf dynamically: see HACKING.)
set -e
top=$(cd "$(dirname "$0")/.." && pwd)
: "${HBNF:?set HBNF to the hbnf executable}"
: "${HBNF_TEMPLATES:?set HBNF_TEMPLATES to hbnf's templates directory}"
export HBNF_TEMPLATES
rev=${HBNF_REV:-$(git -C "$(dirname "$HBNF")" rev-parse --short HEAD 2>/dev/null || echo unknown)}
tmp=$(mktemp)
trap 'rm -f "$tmp"' EXIT
"$HBNF" "$top/grammars/9share.hbnf" --backend=c > "$tmp"
{
cat <<HDR
/*
 * 9share_conf.c -- the parser of 9share.conf (see 9share.conf(5)).
 *
 * Generated by the hbnf parser generator meta compiler, https://github.com/moebiusV/hbnf
 * (revision $rev), from grammars/9share.hbnf.  DO NOT EDIT: change the grammar and run
 * tools/regen-conf.sh (HACKING says how).  The package does not need hbnf to be built.
 *
 * It links with hbnf_conf.c (hbnf's runtime support, ISC licence, copied unchanged).
 */
HDR
sed '1{/^\/\* generated by hbnf/d;}' "$tmp"
} > "$top/src/9share_conf.c.new"
mv "$top/src/9share_conf.c.new" "$top/src/9share_conf.c"
echo "wrote src/9share_conf.c (hbnf $rev)"
